'use client';
// Cadastros gerais: uma tela por grupo de cadastro, com busca e edição. Os dados vêm de
// /api/registry (liberado ao gestor e a quem tem o acesso "Cadastros gerais").
import {useCallback,useEffect,useMemo,useState,FormEvent,ReactNode} from 'react';
import {Package,Plus,Pencil,Search,AlertTriangle,LoaderCircle,Building2,MapPin,Truck,Users,ListChecks,Tags,KeyRound,Unlock,ShieldCheck,History,ArrowUp,ArrowDown,Trash2,Lock,Info,Mail,Copy,Power} from 'lucide-react';
import {toast} from 'sonner';
import {Dialog,DialogContent,DialogHeader,DialogTitle,DialogDescription} from '@/components/ui/dialog';
import {Tabs,TabsList,TabsTrigger,TabsContent} from '@/components/ui/tabs';
import {Table,TableHeader,TableRow,TableHead,TableBody,TableCell} from '@/components/ui/table';
import {Checkbox} from '@/components/ui/checkbox';
import {Skeleton} from '@/components/ui/skeleton';
import {Button} from '@/components/ui/button';
import {Input} from '@/components/ui/input';
import {Textarea} from '@/components/ui/textarea';
import {Choice,Badge,Empty,Field,MultiCheck,Toggle,OrgTag,UNITS,fmt,post,load,type R} from './kit';
import Condition from './condition';

const roles:Record<string,string>={requester:'Solicitante',planner:'Planejador',fueler:'Abastecedor',manager:'Gestor',none:'Sem acesso ao abastecimento'};
const capabilityNames:Record<string,string>={cadastros:'Cadastros gerais',planejamento:'Planejamento',acompanhamento:'Acompanhamento de OS',manutencao:'Manutenção',operacao:'Operação'};
const kindNames:Record<string,string>={unidade:'Unidade',area:'Área',local:'Local'};
const categoryKinds:[string,string,string][]=[['ocorrencia','Ocorrências','Evento ou observação durante a atividade, sem interrupção necessária.'],['impacto','Impactos','Consequência sobre prazo, produtividade, recurso, qualidade ou execução. Não pressupõe parada.'],['bloqueio','Bloqueios','Impedimento que interrompe ou impede a execução de uma etapa.']];
export const moments:Record<string,string>={pre_atividade:'Pré-atividade',pre_uso:'Pré-uso de equipamento',durante:'Durante a atividade',pos_atividade:'Pós-atividade / encerramento'};
const answers=[{value:'C',label:'C'},{value:'NC',label:'NC'},{value:'NA',label:'N/A'}];
const suggestUsername=(name:string)=>{const parts=name.normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().replace(/[^a-z0-9 ]/g,' ').trim().split(/\s+/).filter(Boolean);return parts.length>1?`${parts[0]}.${parts[parts.length-1]}`:parts[0]||''};
const matches=(q:string,...values:unknown[])=>!q||values.join(' ').toLocaleLowerCase('pt-BR').includes(q.toLocaleLowerCase('pt-BR'));
const status=(active:unknown,on='Ativo',off='Inativo')=><Badge tone={active?'success':'muted'}>{active?on:off}</Badge>;
const newKey=()=>crypto.randomUUID().replaceAll('-','').slice(0,16);

type Modal={kind:string,item?:R}|null;

function Panel({title,subtitle,action,children,search,onSearch,placeholder}:{title:string,subtitle?:string,action?:ReactNode,children:ReactNode,search?:string,onSearch?:(v:string)=>void,placeholder?:string}){
 return <section className="n-panel"><div className="panel-heading"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div>{action}</div>{onSearch&&<div className="filters"><div className="search-field"><Search size={17}/><Input value={search} onChange={e=>onSearch(e.target.value)} placeholder={placeholder||'Buscar'} aria-label={placeholder||'Buscar'}/></div></div>}{children}</section>;
}
function Edit({label,onClick}:{label:string,onClick:()=>void}){return <button className="icon-action" onClick={onClick} aria-label={label} title={label}><Pencil size={16}/></button>}

export default function Registry({view,actorId,manager,refreshKey,onChanged}:{view:string,actorId:string,manager:boolean,refreshKey:number,onChanged:()=>void}){
 const [data,setData]=useState<R|null>(null),[error,setError]=useState(''),[modal,setModal]=useState<Modal>(null),[form,setForm]=useState<R>({}),[saving,setSaving]=useState(false),[formError,setFormError]=useState(''),[search,setSearch]=useState(''),[history,setHistory]=useState<R[]|null>(null);
 const [clock]=useState(()=>Date.now());
 const refresh=useCallback(async()=>{try{setData(await load<R>('registry'));setError('')}catch(e){setError((e as Error).message)}},[]);
 // eslint-disable-next-line react-hooks/set-state-in-effect -- Dados recebidos de uma consulta assíncrona ao servidor.
 useEffect(()=>{void refresh()},[refresh,refreshKey]);
 // eslint-disable-next-line react-hooks/set-state-in-effect -- A busca vale para a tela aberta.
 useEffect(()=>{setSearch('')},[view]);
 const set=(key:string,value:unknown)=>setForm(f=>({...f,[key]:value}));
 const byId=useCallback((list:string,id:unknown)=>(data?.[list] as R[]|undefined)?.find(x=>x.id===id),[data]);
 const paths=useMemo(()=>{const list:R[]=data?.locations||[];const out=new Map<string,string>();const path=(l:R,depth=0):string=>{if(out.has(l.id))return out.get(l.id)!;const parent=l.parent_id&&depth<5?list.find(x=>x.id===l.parent_id):null;const p=parent?path(parent,depth+1)+' › '+l.name:l.name;out.set(l.id,p);return p};list.forEach(l=>path(l));return out},[data]);
 const locationPath=(id:unknown)=>paths.get(String(id))||'';
 const options=(list:string,label:(x:R)=>string,keep?:unknown)=>((data?.[list]||[]) as R[]).filter(x=>x.active||x.id===keep||(Array.isArray(keep)&&keep.includes(x.id))).map(x=>({value:x.id,label:label(x)+(x.active?'':' (inativo)')}));

 function open(kind:string,item?:R){
  setFormError('');setModal({kind,item});const base={...item,active:item?!!item.active:true,updatedAt:item?.updated_at};
  if(kind==='org')setForm({...base,name:item?.name||'',acronym:item?.acronym||'',category:item?.category||'cliente',color:item?.color||'#167FA3'});
  else if(kind==='person')setForm({...base,orgId:item?.org_id||'',name:item?.name||'',role:item?.role||'',email:item?.email||'',phone:item?.phone||''});
  else if(kind==='location')setForm({...base,kind:item?.kind||'unidade',parentId:item?.parent_id||'',name:item?.name||'',code:item?.code||'',description:item?.description||''});
  else if(kind==='type'||kind==='function')setForm({...base,name:item?.name||'',description:item?.description||''});
  else if(kind==='material')setForm({...base,name:item?.name||'',unit:item?.unit||'un',description:item?.description||''});
  else if(kind==='sector')setForm({...base,code:item?.code||'',name:item?.name||'',description:item?.description||''});
  else if(kind==='category')setForm({...base,kind:item?.kind||'ocorrencia',name:item?.name||'',description:item?.description||''});
  else if(kind==='equipment')setForm({...base,tag:item?.tag||'',description:item?.description||'',typeId:item?.type_id||'',locationId:item?.location_id||'',capacity:item?.capacity||'',fuelIds:item?.fuel_ids||[]});
  else if(kind==='operator')setForm({...base,name:item?.name||'',badge:item?.badge||'',functionIds:item?.function_ids||[],memberId:item?.member_id||''});
  else if(kind==='member')setForm({...base,name:item?.name||'',username:item?.username||'',email:item?.email||'',role:item?.role||'requester',capabilities:item?.capabilities||[],orgScope:item?.org_scope||[],notifyRequests:item?.notify_requests!==0,notifySchedule:item?.notify_schedule!==0,temporaryPassword:''});
  else if(kind==='resetPassword')setForm({id:item?.id,temporaryPassword:''});
  else if(kind==='checklist'){const v=item?.current;setForm({id:item?.id,code:item?.code||'',expectedVersion:item?.current_version,title:v?.title||'',description:v?.description||'',instructions:v?.instructions||'',moment:v?.moment||'pre_atividade',mandatory:!!v?.mandatory,generalUse:!!v?.general_use,notes:'',activityTypeIds:v?.activity_type_ids||[],equipmentIds:v?.equipment_ids||[],equipmentTypeIds:v?.equipment_type_ids||[],questions:(v?.questions||[]).map((q:R)=>({key:newKey(),text:q.text,required:!!q.required,critical:!!q.critical,target:q.target,allowNa:!!q.allow_na,noteOn:q.note_on}))});if(!item)setForm(f=>({...f,questions:[blankQuestion()]}))}
 }
 const blankQuestion=()=>({key:newKey(),text:'',required:true,critical:false,target:'atividade',allowNa:true,noteOn:['NC','NA']});

 async function submit(e:FormEvent){
  e.preventDefault();if(!modal)return;setSaving(true);setFormError('');
  try{
   const f=form;let path='',body:R={};
   switch(modal.kind){
    case 'org':path='registry/orgs';body={id:f.id,updatedAt:f.updatedAt,name:f.name,acronym:f.acronym,category:f.category,color:f.color,active:f.active};break;
    case 'person':path='registry/people';body={id:f.id,updatedAt:f.updatedAt,orgId:f.orgId,name:f.name,role:f.role,email:f.email||null,phone:f.phone,active:f.active};break;
    case 'location':path='registry/locations';body={id:f.id,updatedAt:f.updatedAt,kind:f.kind,parentId:f.kind==='unidade'?null:f.parentId,name:f.name,code:f.code,description:f.description,active:f.active};break;
    case 'type':path='registry/equipment-types';body={id:f.id,updatedAt:f.updatedAt,name:f.name,description:f.description,active:f.active};break;
    case 'sector':path='registry/sectors';body={id:f.id,updatedAt:f.updatedAt,code:f.code,name:f.name,description:f.description,active:f.active};break;
    case 'material':path='registry/materials';body={id:f.id,updatedAt:f.updatedAt,name:f.name,unit:f.unit,description:f.description,active:f.active};break;
    case 'function':path='registry/functions';body={id:f.id,updatedAt:f.updatedAt,name:f.name,description:f.description,active:f.active};break;
    case 'category':path='registry/categories';body={id:f.id,updatedAt:f.updatedAt,kind:f.kind,name:f.name,description:f.description,active:f.active};break;
    case 'equipment':path='registry/equipment';body={id:f.id,tag:f.tag,description:f.description,typeId:f.typeId,locationId:f.locationId||null,capacity:f.capacity,fuelIds:f.fuelIds,active:f.active};break;
    case 'operator':path='registry/operators';body={id:f.id,name:f.name,badge:f.badge,functionIds:f.functionIds,memberId:f.memberId||null,active:f.active};break;
    case 'member':path='members';body={id:f.id,username:f.username,name:f.name,email:f.email||null,role:f.role,capabilities:f.role==='manager'?[]:f.capabilities,orgScope:f.role==='manager'?[]:f.orgScope,notifyRequests:f.notifyRequests,notifySchedule:f.notifySchedule,active:f.active,...(!f.id&&f.temporaryPassword?{temporaryPassword:f.temporaryPassword}:{})};break;
    case 'resetPassword':path='members/reset-password';body={id:f.id,...(f.temporaryPassword?{temporaryPassword:f.temporaryPassword}:{})};break;
    case 'checklist':path='registry/checklists';body={id:f.id,code:f.code,expectedVersion:f.expectedVersion,title:f.title,description:f.description,instructions:f.instructions,moment:f.moment,mandatory:f.mandatory,generalUse:f.generalUse,notes:f.notes,links:{activityTypeIds:f.activityTypeIds,equipmentIds:f.equipmentIds,equipmentTypeIds:f.equipmentTypeIds},questions:f.questions.map(({key:_k,...q}:R)=>{void _k;return q})};break;
   }
   const result=await post(path,body);setModal(null);toast.success(typeof result.message==='string'?result.message:'Salvo com sucesso.');await refresh();
   // Equipamentos e colaboradores também aparecem nos formulários de abastecimento.
   if(['equipment','operator','type','member'].includes(modal.kind))onChanged();
  }catch(err){setFormError(err instanceof Error?err.message:'Não foi possível salvar.')}finally{setSaving(false)}
 }
 async function action(path:string,body:R,done:string){try{const r=await post(path,body);toast.success(r.message||done);await refresh()}catch(e){toast.error((e as Error).message)}}
 async function showHistory(item:R){setHistory([]);try{const r=await load<R>('registry/checklist-versions?id='+encodeURIComponent(item.id));setHistory(r.versions)}catch(e){setHistory(null);toast.error((e as Error).message)}}

 const orgs:R[]=useMemo(()=>data?.orgs||[],[data]),people:R[]=data?.people||[],locations:R[]=useMemo(()=>data?.locations||[],[data]);
 const tree=useMemo(()=>{const out:R[]=[];const walk=(parent:string|null,depth:number)=>{for(const l of locations.filter(x=>(x.parent_id||null)===parent)){out.push({...l,depth});walk(l.id,depth+1)}};walk(null,0);return out},[locations]);

 if(error)return <div className="error-panel"><AlertTriangle/><h2>Não foi possível abrir os cadastros</h2><p>{error}</p><Button onClick={()=>void refresh()}>Tentar novamente</Button></div>;
 if(!data)return <div className="loading-grid"><Skeleton className="h-64 rounded-xl"/><Skeleton className="h-64 rounded-xl"/></div>;
 const q=search;

 return <div className="registry">
  {view==='cad-solicitantes'&&<Tabs defaultValue="orgs"><TabsList className="n-tabs"><TabsTrigger value="orgs">Organizações</TabsTrigger><TabsTrigger value="people">Pessoas solicitantes</TabsTrigger><TabsTrigger value="sectors">Setores (código da OS)</TabsTrigger></TabsList>
   <TabsContent value="orgs"><Panel title="Organizações solicitantes" subtitle={`${orgs.filter(o=>o.active).length} ativas · ${orgs.filter(o=>o.active&&o.category==='interna').length} internas · ${orgs.filter(o=>o.active&&o.category==='cliente').length} clientes`} action={<Button onClick={()=>open('org')}><Plus size={16}/> Nova organização</Button>} search={q} onSearch={setSearch} placeholder="Nome ou sigla">
    {orgs.length?<div className="table-scroll"><Table><TableHeader><TableRow><TableHead>Etiqueta</TableHead><TableHead>Nome</TableHead><TableHead>Categoria</TableHead><TableHead>Pessoas</TableHead><TableHead>Situação</TableHead><TableHead/></TableRow></TableHeader><TableBody>{orgs.filter(o=>matches(q,o.name,o.acronym)).map(o=><TableRow key={o.id}><TableCell><OrgTag org={o}/></TableCell><TableCell><b>{o.name}</b></TableCell><TableCell>{o.category==='interna'?'Operação interna':'Cliente'}</TableCell><TableCell>{people.filter(p=>p.org_id===o.id&&p.active).length}</TableCell><TableCell>{status(o.active)}</TableCell><TableCell><Edit label={`Editar ${o.name}`} onClick={()=>open('org',o)}/></TableCell></TableRow>)}</TableBody></Table></div>:<Empty icon={Building2} title="Quem solicita as atividades?" description="Cadastre a operação interna e os clientes. Cada OS será classificada por uma organização, com etiqueta de texto e cor." action={<Button onClick={()=>open('org')}><Plus size={16}/> Cadastrar organização</Button>}/>}
   </Panel></TabsContent>
   <TabsContent value="people"><Panel title="Pessoas solicitantes" subtitle="Contato de cada organização para as solicitações e o planejamento." action={<Button onClick={()=>open('person')} disabled={!orgs.some(o=>o.active)}><Plus size={16}/> Nova pessoa</Button>} search={q} onSearch={setSearch} placeholder="Nome, organização ou contato">
    {people.length?<div className="table-scroll"><Table><TableHeader><TableRow><TableHead>Nome</TableHead><TableHead>Organização</TableHead><TableHead>Cargo ou função</TableHead><TableHead>Contato</TableHead><TableHead>Situação</TableHead><TableHead/></TableRow></TableHeader><TableBody>{people.filter(p=>matches(q,p.name,p.role,p.email,p.phone,byId('orgs',p.org_id)?.name,byId('orgs',p.org_id)?.acronym)).map(p=><TableRow key={p.id}><TableCell><b>{p.name}</b></TableCell><TableCell><OrgTag org={byId('orgs',p.org_id)}/></TableCell><TableCell>{p.role||'—'}</TableCell><TableCell>{p.email||p.phone?<>{p.email}{p.phone&&<small>{p.phone}</small>}</>:'—'}</TableCell><TableCell>{status(p.active)}</TableCell><TableCell><Edit label={`Editar ${p.name}`} onClick={()=>open('person',p)}/></TableCell></TableRow>)}</TableBody></Table></div>:<Empty icon={Users} title="Nenhuma pessoa solicitante" description={orgs.length?'Cadastre as pessoas de contato de cada organização.':'Cadastre primeiro uma organização.'}/>}
   </Panel></TabsContent>
   <TabsContent value="sectors"><Panel title="Setores" subtitle="Cada OS recebe o código de um setor: é o filtro do Painel de OS, da Lista de OS e da agenda em PDF. O código não muda depois de criado." action={<Button onClick={()=>open('sector')}><Plus size={16}/> Novo setor</Button>} search={q} onSearch={setSearch} placeholder="Código ou nome">
    {(data.sectors||[]).length?<div className="table-scroll"><Table><TableHeader><TableRow><TableHead>Código</TableHead><TableHead>Setor</TableHead><TableHead>Descrição</TableHead><TableHead>OS</TableHead><TableHead>Situação</TableHead><TableHead/></TableRow></TableHeader><TableBody>{(data.sectors as R[]).filter(x=>matches(q,x.code,x.name,x.description)).map(x=><TableRow key={x.id}><TableCell><b className="tag-label mono">{x.code}</b></TableCell><TableCell><b>{x.name}</b></TableCell><TableCell className="reason-cell">{x.description||'—'}</TableCell><TableCell>{x.orders}</TableCell><TableCell>{status(x.active)}</TableCell><TableCell><Edit label={`Editar ${x.code}`} onClick={()=>open('sector',x)}/></TableCell></TableRow>)}</TableBody></Table></div>:<Empty icon={Building2} title="Nenhum setor cadastrado" description="Ex.: MNT-01 · Manutenção. O Planejamento e a Operação também podem cadastrar na hora." action={<Button onClick={()=>open('sector')}><Plus size={16}/> Cadastrar setor</Button>}/>}
   </Panel></TabsContent></Tabs>}

  {view==='cad-locais'&&<Panel title="Locais" subtitle="Unidade › área › local. O nível é definido na criação; inativar preserva o histórico." action={<Button onClick={()=>open('location')}><Plus size={16}/> Novo local</Button>} search={q} onSearch={setSearch} placeholder="Nome ou código">
   {tree.length?<div className="table-scroll"><Table><TableHeader><TableRow><TableHead>Local</TableHead><TableHead>Nível</TableHead><TableHead>Código</TableHead><TableHead>Equipamentos</TableHead><TableHead>Situação</TableHead><TableHead/></TableRow></TableHeader><TableBody>{tree.filter(l=>matches(q,l.name,l.code,locationPath(l.id))).map(l=><TableRow key={l.id}><TableCell><span className="tree-cell" style={{paddingLeft:q?0:l.depth*22}}>{l.depth>0&&!q&&<i aria-hidden>└</i>}<b>{q?locationPath(l.id):l.name}</b></span>{l.description&&<small>{l.description}</small>}</TableCell><TableCell><Badge tone={l.kind==='unidade'?'info':'muted'}>{kindNames[l.kind]}</Badge></TableCell><TableCell>{l.code||'—'}</TableCell><TableCell>{data.equipment.filter((e:R)=>e.location_id===l.id).length||'—'}</TableCell><TableCell>{status(l.active)}</TableCell><TableCell><Edit label={`Editar ${l.name}`} onClick={()=>open('location',l)}/></TableCell></TableRow>)}</TableBody></Table></div>:<Empty icon={MapPin} title="Onde as atividades acontecem?" description="Comece pela unidade (ex.: Base Açu), depois cadastre áreas e locais específicos." action={<Button onClick={()=>open('location')}><Plus size={16}/> Cadastrar unidade</Button>}/>}
  </Panel>}

  {view==='cad-equipamentos'&&<Tabs defaultValue="equipment"><TabsList className="n-tabs"><TabsTrigger value="equipment">Equipamentos</TabsTrigger><TabsTrigger value="types">Tipos de equipamento</TabsTrigger><TabsTrigger value="materials">Materiais</TabsTrigger><TabsTrigger value="condition">Condição técnica</TabsTrigger></TabsList>
   <TabsContent value="equipment"><Panel title="Equipamentos" subtitle={`${data.equipment.filter((e:R)=>e.active).length} ativos · identificados pela TAG`} action={<Button onClick={()=>open('equipment')} disabled={!data.equipmentTypes.some((t:R)=>t.active)}><Plus size={16}/> Novo equipamento</Button>} search={q} onSearch={setSearch} placeholder="TAG, descrição ou tipo">
    {data.equipment.length?<div className="table-scroll"><Table><TableHeader><TableRow><TableHead>TAG</TableHead><TableHead>Descrição</TableHead><TableHead>Tipo</TableHead><TableHead>Capacidade</TableHead><TableHead>Local</TableHead><TableHead>Combustíveis</TableHead><TableHead>Situação</TableHead><TableHead/></TableRow></TableHeader><TableBody>{data.equipment.filter((e:R)=>matches(q,e.tag,e.description,e.type)).map((e:R)=><TableRow key={e.id}><TableCell><b className="tag-label">{e.tag}</b></TableCell><TableCell>{e.description}</TableCell><TableCell>{byId('equipmentTypes',e.type_id)?.name||<span className="pending-text">{e.type||'Definir tipo'}</span>}</TableCell><TableCell>{e.capacity||'—'}</TableCell><TableCell>{e.location_id?locationPath(e.location_id):'—'}</TableCell><TableCell><div className="badge-group">{e.fuel_ids.map((fid:string)=><Badge key={fid} tone="info">{byId('fuels',fid)?.name||fid}</Badge>)}</div></TableCell><TableCell>{status(e.active)}</TableCell><TableCell><Edit label={`Editar ${e.tag}`} onClick={()=>open('equipment',e)}/></TableCell></TableRow>)}</TableBody></Table></div>:<Empty icon={Truck} title="Cadastre o primeiro equipamento" description="Informe a TAG, o tipo e os combustíveis compatíveis."/>}
   </Panel></TabsContent>
   <TabsContent value="types"><Panel title="Tipos de equipamento" subtitle="Usados nas necessidades das etapas e nos vínculos de checklist." action={<Button onClick={()=>open('type')}><Plus size={16}/> Novo tipo</Button>} search={q} onSearch={setSearch} placeholder="Nome do tipo">
    {data.equipmentTypes.length?<div className="table-scroll"><Table><TableHeader><TableRow><TableHead>Tipo</TableHead><TableHead>Descrição</TableHead><TableHead>Equipamentos</TableHead><TableHead>Situação</TableHead><TableHead/></TableRow></TableHeader><TableBody>{data.equipmentTypes.filter((t:R)=>matches(q,t.name,t.description)).map((t:R)=><TableRow key={t.id}><TableCell><b>{t.name}</b></TableCell><TableCell className="reason-cell">{t.description||'—'}</TableCell><TableCell>{t.equipment_count}</TableCell><TableCell>{status(t.active)}</TableCell><TableCell><Edit label={`Editar ${t.name}`} onClick={()=>open('type',t)}/></TableCell></TableRow>)}</TableBody></Table></div>:<Empty icon={Truck} title="Nenhum tipo cadastrado" description="Ex.: Empilhadeira, PTA, Guindaste." action={<Button onClick={()=>open('type')}><Plus size={16}/> Cadastrar tipo</Button>}/>}
   </Panel></TabsContent>
   <TabsContent value="materials"><Panel title="Materiais" subtitle="Consumíveis, peças e insumos usados no planejamento de recursos, com a unidade de medida padrão." action={<Button onClick={()=>open('material')}><Plus size={16}/> Novo material</Button>} search={q} onSearch={setSearch} placeholder="Nome do material">
    {data.materials.length?<div className="table-scroll"><Table><TableHeader><TableRow><TableHead>Material</TableHead><TableHead>Unidade</TableHead><TableHead>Descrição</TableHead><TableHead>Situação</TableHead><TableHead/></TableRow></TableHeader><TableBody>{data.materials.filter((m:R)=>matches(q,m.name,m.description)).map((m:R)=><TableRow key={m.id}><TableCell><b>{m.name}</b></TableCell><TableCell><span className="mono">{m.unit}</span></TableCell><TableCell className="reason-cell">{m.description||'—'}</TableCell><TableCell>{status(m.active)}</TableCell><TableCell><Edit label={`Editar ${m.name}`} onClick={()=>open('material',m)}/></TableCell></TableRow>)}</TableBody></Table></div>:<Empty icon={Package} title="Nenhum material cadastrado" description="Ex.: Cinta de amarração (un), Óleo hidráulico (L). O Planejamento também pode cadastrar na hora." action={<Button onClick={()=>open('material')}><Plus size={16}/> Cadastrar material</Button>}/>}
   </Panel></TabsContent>
   <TabsContent value="condition"><Condition equipment={data.equipment} refreshKey={refreshKey}/></TabsContent></Tabs>}

  {view==='cad-colaboradores'&&<Tabs defaultValue="operators"><TabsList className="n-tabs"><TabsTrigger value="operators">Colaboradores</TabsTrigger><TabsTrigger value="functions">Funções</TabsTrigger>{manager&&<TabsTrigger value="members">Usuários e acessos</TabsTrigger>}{manager&&<TabsTrigger value="audit">Histórico de alterações</TabsTrigger>}</TabsList>
   <TabsContent value="operators"><Panel title="Colaboradores" subtitle="A pessoa que opera o equipamento pode ser diferente de quem registra no sistema." action={<Button onClick={()=>open('operator')}><Plus size={16}/> Novo colaborador</Button>} search={q} onSearch={setSearch} placeholder="Nome, matrícula ou função">
    {data.operators.length?<div className="table-scroll"><Table><TableHeader><TableRow><TableHead>Colaborador</TableHead><TableHead>Matrícula</TableHead><TableHead>Funções</TableHead><TableHead>Usuário de acesso</TableHead><TableHead>Situação</TableHead><TableHead/></TableRow></TableHeader><TableBody>{data.operators.filter((o:R)=>matches(q,o.name,o.badge,...o.function_ids.map((f:string)=>byId('functions',f)?.name))).map((o:R)=><TableRow key={o.id}><TableCell><span className="name-cell"><span className="table-avatar">{o.name.slice(0,2).toUpperCase()}</span><b>{o.name}</b></span></TableCell><TableCell>{o.badge||'—'}</TableCell><TableCell><div className="badge-group wrap">{o.function_ids.length?o.function_ids.map((f:string)=><Badge key={f} tone="info">{byId('functions',f)?.name}</Badge>):'—'}</div></TableCell><TableCell>{o.member_username?<span className="tag-label">{o.member_username}</span>:<span className="pending-text">Sem usuário</span>}</TableCell><TableCell>{status(o.active)}</TableCell><TableCell><Edit label={`Editar ${o.name}`} onClick={()=>open('operator',o)}/></TableCell></TableRow>)}</TableBody></Table></div>:<Empty icon={Users} title="Quem faz parte da operação?" description="Cadastre os colaboradores e suas funções."/>}
   </Panel></TabsContent>
   <TabsContent value="functions"><Panel title="Funções" subtitle="Usadas nas necessidades padrão das etapas do fluxo." action={<Button onClick={()=>open('function')}><Plus size={16}/> Nova função</Button>} search={q} onSearch={setSearch} placeholder="Nome da função">
    {data.functions.length?<div className="table-scroll"><Table><TableHeader><TableRow><TableHead>Função</TableHead><TableHead>Descrição</TableHead><TableHead>Colaboradores</TableHead><TableHead>Situação</TableHead><TableHead/></TableRow></TableHeader><TableBody>{data.functions.filter((f:R)=>matches(q,f.name,f.description)).map((f:R)=><TableRow key={f.id}><TableCell><b>{f.name}</b></TableCell><TableCell className="reason-cell">{f.description||'—'}</TableCell><TableCell>{data.operators.filter((o:R)=>o.active&&o.function_ids.includes(f.id)).length}</TableCell><TableCell>{status(f.active)}</TableCell><TableCell><Edit label={`Editar ${f.name}`} onClick={()=>open('function',f)}/></TableCell></TableRow>)}</TableBody></Table></div>:<Empty icon={Users} title="Nenhuma função cadastrada" description="Ex.: Operador de empilhadeira, Sinaleiro, Conferente." action={<Button onClick={()=>open('function')}><Plus size={16}/> Cadastrar função</Button>}/>}
   </Panel></TabsContent>
   {manager&&<TabsContent value="members"><Panel title="Usuários e acessos" subtitle="Cada pessoa entra com o usuário e a senha padrão no primeiro acesso e define a senha definitiva." action={<Button onClick={()=>open('member')}><Plus size={16}/> Novo usuário</Button>} search={q} onSearch={setSearch} placeholder="Nome, usuário ou e-mail">
    {data.access&&<div className="default-password"><span><KeyRound size={16} className="inline mr-2"/>Senha padrão de primeiro acesso: {data.access.defaultPassword?<code>{data.access.defaultPassword}</code>:<b>não configurada no servidor</b>}</span><small>Vale por {data.access.temporaryPasswordDays} dias após a criação ou redefinição. Depois disso, redefina a senha.</small></div>}
    <div className="table-scroll"><Table><TableHeader><TableRow><TableHead>Nome</TableHead><TableHead>Usuário</TableHead><TableHead>E-mail para avisos</TableHead><TableHead>Perfil e acessos</TableHead><TableHead>Senha</TableHead><TableHead>Último acesso</TableHead><TableHead>Situação</TableHead><TableHead/></TableRow></TableHeader><TableBody>{data.members.filter((m:R)=>matches(q,m.name,m.username,m.email)).map((m:R)=>{const locked=!!m.locked_until&&new Date(m.locked_until).valueOf()>clock;const expired=!!m.must_change_password&&!!m.password_changed_at&&new Date(m.password_changed_at).valueOf()+(data.access?.temporaryPasswordDays||7)*86400000<clock;return <TableRow key={m.id}><TableCell><b>{m.name}</b>{m.id===actorId&&<small>Você</small>}</TableCell><TableCell><span className="tag-label">{m.username}</span></TableCell><TableCell>{m.email||<span className="pending-text">Sem e-mail</span>}</TableCell><TableCell><div className="badge-group wrap"><Badge tone="info">{roles[m.role]}</Badge>{m.role==='manager'?<Badge tone="success">Todos os módulos</Badge>:<>{(m.capabilities||[]).map((c:string)=><Badge key={c} tone="success">{capabilityNames[c]}</Badge>)}{(m.org_scope||[]).length>0&&<Badge tone="warning">Só {(m.org_scope as string[]).map(o=>byId('orgs',o)?.acronym).join(', ')}</Badge>}</>}</div></TableCell><TableCell><div className="access-status">{locked?<Badge tone="danger">Bloqueado por tentativas</Badge>:expired?<Badge tone="danger">Senha provisória expirada</Badge>:m.must_change_password?<Badge tone="warning">Primeiro acesso pendente</Badge>:<Badge tone="success">Senha definida</Badge>}{m.password_changed_at&&<small>{m.must_change_password?'Senha provisória desde':'Alterada em'} {fmt(m.password_changed_at)}</small>}</div></TableCell><TableCell>{m.last_login_at?fmt(m.last_login_at):<span className="pending-text">Nunca entrou</span>}</TableCell><TableCell>{status(m.active,'Liberado','Desativado')}</TableCell><TableCell><div className="access-actions">{locked&&<button className="icon-action" onClick={()=>void action('members/unlock',{id:m.id},'Acesso desbloqueado.')} title="Desbloquear" aria-label={`Desbloquear ${m.name}`}><Unlock size={16}/></button>}{m.id!==actorId&&<button className="icon-action" onClick={()=>open('resetPassword',m)} title="Redefinir senha" aria-label={`Redefinir senha de ${m.name}`}><KeyRound size={16}/></button>}<Edit label={`Editar usuário ${m.name}`} onClick={()=>open('member',m)}/></div></TableCell></TableRow>})}</TableBody></Table></div>
   </Panel>
   <div className="permission-grid">{[['Solicitante','Solicita abastecimentos e acompanha somente seus pedidos.'],['Planejador','Recebe solicitações de abastecimento, define horários e mantém a agenda.'],['Abastecedor','Consulta a agenda compartilhada e registra o consumo.'],['Gestor','Todos os módulos: estoque, correções, cadastros, fluxos, usuários, senhas e exportações.'],['+ Cadastros gerais','Acesso adicional: solicitantes, locais, equipamentos, colaboradores, checklists e categorias. Não inclui usuários e senhas.'],['+ Planejamento','Acesso adicional: fluxos, planejamento de atividade, rascunhos, lançamento e cancelamento de OS.'],['+ Operação','Acesso adicional: inicia, bloqueia, pausa, retoma e finaliza etapas, registra apontamentos e preenche checklists nas OS.'],['+ Acompanhamento de OS','Acesso adicional: consulta das OS lançadas, limitada às organizações marcadas no usuário.'],['+ Manutenção','Acesso adicional: critérios, preventivas, corretivas e leituras; registra impedimentos e faz a liberação técnica de equipamentos, com justificativa e evidência.'],['Sem acesso ao abastecimento','Perfil para quem só usa os outros módulos (ex.: clientes que acompanham suas OS).']].map(([role,description])=><section className="n-panel" key={role}><ShieldCheck size={22}/><h3>{role}</h3><p>{description}</p></section>)}</div>
   </TabsContent>}
   {manager&&<TabsContent value="audit"><Panel title="Últimas alterações" subtitle="Trilha de auditoria: cadastros, acessos, estoque e correções.">{data.audits.length?<div className="table-scroll"><Table><TableHeader><TableRow><TableHead>Data</TableHead><TableHead>Ação</TableHead><TableHead>Responsável</TableHead><TableHead>Detalhes</TableHead></TableRow></TableHeader><TableBody>{data.audits.map((a:R)=><TableRow key={a.id}><TableCell>{fmt(a.created_at)}</TableCell><TableCell>{a.action}</TableCell><TableCell>{a.author_name}</TableCell><TableCell><details><summary>Ver alteração</summary><pre>{JSON.stringify(JSON.parse(a.detail),null,2)}</pre></details></TableCell></TableRow>)}</TableBody></Table></div>:<Empty icon={History} title="Histórico preservado" description="As alterações ficarão registradas aqui."/>}</Panel></TabsContent>}
  </Tabs>}

  {view==='cad-checklists'&&<Panel title="Modelos de checklist" subtitle="Cada alteração publica uma nova versão; preenchimentos antigos mantêm a versão aplicada." action={<Button onClick={()=>open('checklist')}><Plus size={16}/> Novo checklist</Button>} search={q} onSearch={setSearch} placeholder="Código ou título">
   {data.checklists.length?<div className="table-scroll"><Table><TableHeader><TableRow><TableHead>Checklist</TableHead><TableHead>Momento</TableHead><TableHead>Perguntas</TableHead><TableHead>Aplicação</TableHead><TableHead>Versão</TableHead><TableHead>Situação</TableHead><TableHead/></TableRow></TableHeader><TableBody>{data.checklists.filter((c:R)=>matches(q,c.code,c.current?.title)).map((c:R)=>{const v=c.current||{};const links=[...(v.activity_type_ids||[]).map((x:string)=>byId('activityTypes',x)?.code),...(v.equipment_type_ids||[]).map((x:string)=>byId('equipmentTypes',x)?.name),...(v.equipment_ids||[]).map((x:string)=>byId('equipment',x)?.tag)].filter(Boolean);const critical=(v.questions||[]).filter((x:R)=>x.critical).length;return <TableRow key={c.id}><TableCell><b>{v.title}</b><small>{c.code}</small></TableCell><TableCell>{moments[v.moment]}{v.mandatory?<small>Obrigatório</small>:<small>Opcional</small>}</TableCell><TableCell>{(v.questions||[]).length}{critical>0&&<small className="danger-text">{critical} crítica{critical>1?'s':''}</small>}</TableCell><TableCell className="reason-cell">{v.general_use?<Badge tone="info">Uso geral</Badge>:null} {links.join(' · ')}</TableCell><TableCell>v{c.current_version}<small>{fmt(v.created_at,true)} · {v.created_by_name}</small></TableCell><TableCell>{status(c.active)}</TableCell><TableCell><div className="access-actions"><Edit label={`Editar ${c.code}`} onClick={()=>open('checklist',c)}/><button className="icon-action" onClick={()=>void showHistory(c)} aria-label={`Versões de ${c.code}`} title="Versões"><History size={16}/></button><button className="icon-action" onClick={()=>void action('registry/checklists/status',{id:c.id,active:!c.active,updatedAt:c.updated_at},c.active?'Checklist inativado.':'Checklist reativado.')} aria-label={c.active?`Inativar ${c.code}`:`Reativar ${c.code}`} title={c.active?'Inativar':'Reativar'}><Power size={16}/></button></div></TableCell></TableRow>})}</TableBody></Table></div>:<Empty icon={ListChecks} title="Nenhum modelo de checklist" description="Crie checklists com respostas C, NC e N/A, vinculados a tipos de atividade, tipos de equipamento ou equipamentos específicos." action={<Button onClick={()=>open('checklist')}><Plus size={16}/> Criar checklist</Button>}/>}
   <div className="notice inline"><Lock size={17}/><span>Uma pergunta <b>crítica sobre equipamento</b> respondida NC bloqueará o equipamento em todo o sistema assim que o preenchimento na OS estiver disponível (módulo Operação). A liberação será feita somente pelo futuro módulo de Manutenção; não há botão de desbloqueio nos cadastros.</span></div>
  </Panel>}

  {view==='cad-categorias'&&<div className="category-grid">{categoryKinds.map(([kind,label,meaning])=><Panel key={kind} title={label} subtitle={meaning} action={<Button variant="outline" onClick={()=>{open('category');setForm(f=>({...f,kind}))}}><Plus size={16}/> Nova</Button>}>
   {data.categories.some((c:R)=>c.kind===kind)?<ul className="category-list">{data.categories.filter((c:R)=>c.kind===kind).map((c:R)=><li key={c.id}><div><b>{c.name}</b>{c.description&&<small>{c.description}</small>}</div>{status(c.active)}<Edit label={`Editar ${c.name}`} onClick={()=>open('category',c)}/></li>)}</ul>:<Empty icon={Tags} title="Nenhuma categoria" description="Ex.: clima, falta de material, interferência de terceiros."/>}
  </Panel>)}</div>}

  <Dialog open={!!modal} onOpenChange={v=>{if(!saving&&!v)setModal(null)}}><DialogContent className={`n-dialog ${modal?.kind==='checklist'?'n-dialog-wide':''}`}><DialogHeader><div className="modal-eyebrow"><ShieldCheck size={16}/> CADASTROS GERAIS</div><DialogTitle>{{org:'Organização solicitante',person:'Pessoa solicitante',location:'Local',type:'Tipo de equipamento',function:'Função',material:'Material',sector:'Setor',category:'Categoria de apontamento',equipment:'Equipamento',operator:'Colaborador',member:'Usuário de acesso',resetPassword:'Redefinir senha',checklist:'Modelo de checklist'}[modal?.kind||'']||'Cadastro'}{modal?.item&&modal.kind!=='resetPassword'?' · edição':''}</DialogTitle><DialogDescription>{modal?.kind==='checklist'?(modal.item?`Salvar publica a versão ${(modal.item.current_version||0)+1}. A versão ${modal.item.current_version} continua valendo para o que já foi preenchido.`:'O checklist nasce na versão 1.'):modal?.kind==='resetPassword'?`A pessoa entrará com a senha provisória e definirá uma nova senha. As sessões abertas de ${modal.item?.name} serão encerradas.`:'Campos com * são obrigatórios. Desativar preserva o histórico.'}</DialogDescription></DialogHeader>
   <form onSubmit={submit}><div className="form-grid">
    {modal?.kind==='org'&&<><Field label="Nome *" wide><Input required maxLength={120} value={form.name} onChange={e=>set('name',e.target.value)} placeholder="Ex.: Operação interna, Cliente X"/></Field><Field label="Sigla *" hint="Até 12 letras ou números."><Input required maxLength={12} value={form.acronym} onChange={e=>set('acronym',e.target.value.toUpperCase())}/></Field><Field label="Categoria *"><Choice value={form.category} onChange={v=>set('category',v)} options={[{value:'interna',label:'Operação interna'},{value:'cliente',label:'Cliente'}]}/></Field><Field label="Cor da etiqueta *" hint="O texto da etiqueta ajusta o contraste automaticamente."><div className="color-field"><input type="color" aria-label="Escolher cor" value={form.color} onChange={e=>set('color',e.target.value.toUpperCase())}/><Input maxLength={7} value={form.color} onChange={e=>set('color',e.target.value.toUpperCase())} aria-label="Cor em hexadecimal"/></div></Field><div className="n-field"><label>Prévia</label><OrgTag org={{name:form.name||'Organização',acronym:form.acronym||'SIGLA',color:/^#[0-9A-F]{6}$/.test(form.color)?form.color:'#167FA3'}}/></div></>}
    {modal?.kind==='person'&&<><Field label="Nome *" wide><Input required maxLength={180} value={form.name} onChange={e=>set('name',e.target.value)}/></Field><Field label="Organização *" wide><Choice value={form.orgId} onChange={v=>set('orgId',v)} options={options('orgs',o=>`${o.acronym} · ${o.name}`,form.orgId)}/></Field><Field label="Cargo ou função"><Input maxLength={120} value={form.role} onChange={e=>set('role',e.target.value)}/></Field><Field label="Telefone"><Input maxLength={40} value={form.phone} onChange={e=>set('phone',e.target.value)}/></Field><Field label="E-mail" wide><Input type="email" maxLength={254} value={form.email} onChange={e=>set('email',e.target.value)}/></Field></>}
    {modal?.kind==='location'&&<><Field label="Nível *" hint={modal.item?'O nível não muda depois da criação.':undefined}><Choice disabled={!!modal.item} value={form.kind} onChange={v=>setForm(f=>({...f,kind:v,parentId:''}))} options={Object.entries(kindNames).map(([value,label])=>({value,label}))}/></Field>{form.kind!=='unidade'&&<Field label={form.kind==='area'?'Unidade *':'Unidade ou área *'}><Choice value={form.parentId} onChange={v=>set('parentId',v)} options={locations.filter(l=>(l.active||l.id===form.parentId)&&l.id!==form.id&&(form.kind==='area'?l.kind==='unidade':l.kind!=='local')).map(l=>({value:l.id,label:locationPath(l.id)}))}/></Field>}<Field label="Nome *" wide><Input required maxLength={120} value={form.name} onChange={e=>set('name',e.target.value)}/></Field><Field label="Código"><Input maxLength={30} value={form.code} onChange={e=>set('code',e.target.value.toUpperCase())}/></Field><Field label="Descrição" wide><Textarea maxLength={500} value={form.description} onChange={e=>set('description',e.target.value)}/></Field></>}
    {(modal?.kind==='type'||modal?.kind==='function')&&<><Field label="Nome *" wide><Input required maxLength={100} value={form.name} onChange={e=>set('name',e.target.value)}/></Field><Field label="Descrição" wide><Textarea maxLength={500} value={form.description} onChange={e=>set('description',e.target.value)}/></Field>{modal.kind==='type'&&modal.item&&<div className="notice wide"><Info size={17}/><span>Renomear o tipo atualiza o nome exibido nos equipamentos vinculados.</span></div>}</>}
    {modal?.kind==='sector'&&<><Field label="Código *" hint={form.id?'O código identifica o setor nas OS e não muda.':'Letras, números, ponto, barra, hífen ou sublinhado (até 30).'}><Input required disabled={!!form.id} maxLength={30} value={form.code} onChange={e=>set('code',e.target.value.toUpperCase().replace(/\s+/g,''))} placeholder="Ex.: MNT-01"/></Field><Field label="Nome do setor *"><Input required maxLength={120} value={form.name} onChange={e=>set('name',e.target.value)} placeholder="Ex.: Manutenção"/></Field><Field label="Descrição" wide><Textarea maxLength={500} value={form.description} onChange={e=>set('description',e.target.value)}/></Field></>}
    {modal?.kind==='material'&&<><Field label="Nome *" wide><Input required maxLength={100} value={form.name} onChange={e=>set('name',e.target.value)} placeholder="Ex.: Cinta de amarração 5 t"/></Field><Field label="Unidade de medida *" hint="Ex.: un, kg, t, L, m, m², m³, cx, pç."><Input required maxLength={12} list="units" value={form.unit} onChange={e=>set('unit',e.target.value)}/><datalist id="units">{UNITS.map(u=><option key={u} value={u}/>)}</datalist></Field><Field label="Descrição" wide><Textarea maxLength={500} value={form.description} onChange={e=>set('description',e.target.value)}/></Field></>}
    {modal?.kind==='category'&&<><Field label="Tipo *" wide hint={modal.item?'O tipo não muda depois da criação.':undefined}><Choice disabled={!!modal.item} value={form.kind} onChange={v=>set('kind',v)} options={categoryKinds.map(([value,label])=>({value,label}))}/></Field><Field label="Nome *" wide><Input required maxLength={100} value={form.name} onChange={e=>set('name',e.target.value)}/></Field><Field label="Descrição" wide><Textarea maxLength={500} value={form.description} onChange={e=>set('description',e.target.value)}/></Field></>}
    {modal?.kind==='equipment'&&<><Field label="TAG *" hint="Identificação única (patrimônio ou código)."><Input required maxLength={60} value={form.tag} onChange={e=>set('tag',e.target.value)} placeholder="Ex.: EMP-01"/></Field><Field label="Tipo *"><Choice value={form.typeId} onChange={v=>set('typeId',v)} options={options('equipmentTypes',t=>t.name,form.typeId)}/></Field><Field label="Descrição *" wide><Input required maxLength={250} value={form.description} onChange={e=>set('description',e.target.value)}/></Field><Field label="Capacidade" hint="Ex.: 4,5 t · 16 t · 12 m"><Input maxLength={60} value={form.capacity} onChange={e=>set('capacity',e.target.value)}/></Field><Field label="Local de base"><Choice value={form.locationId||'none'} onChange={v=>set('locationId',v==='none'?'':v)} options={[{value:'none',label:'Sem local definido'},...locations.filter(l=>l.active||l.id===form.locationId).map(l=>({value:l.id,label:locationPath(l.id)}))]}/></Field><MultiCheck label="Combustíveis permitidos *" options={options('fuels',f=>f.name,form.fuelIds)} value={form.fuelIds} onChange={v=>set('fuelIds',v)}/></>}
    {modal?.kind==='operator'&&<><Field label="Nome *" wide><Input required maxLength={180} value={form.name} onChange={e=>set('name',e.target.value)}/></Field><Field label="Matrícula"><Input maxLength={60} value={form.badge} onChange={e=>set('badge',e.target.value)}/></Field>{manager?<Field label="Usuário de acesso" hint="Vincule quando o colaborador também entra no sistema."><Choice value={form.memberId||'none'} onChange={v=>set('memberId',v==='none'?'':v)} options={[{value:'none',label:'Sem usuário'},...data.members.filter((m:R)=>m.active||m.id===form.memberId).map((m:R)=>({value:m.id,label:`${m.name} (${m.username})`}))]}/></Field>:<div className="n-field"><label>Usuário de acesso</label><small>{modal.item?.member_username||'Sem usuário'} · somente o gestor altera.</small></div>}<MultiCheck label="Funções" options={options('functions',f=>f.name,form.functionIds)} value={form.functionIds} onChange={v=>set('functionIds',v)} empty="Cadastre as funções na aba Funções."/></>}
    {modal?.kind==='member'&&<><Field label="Nome completo *" wide><Input required maxLength={180} value={form.name} onChange={e=>{const name=e.target.value;setForm(f=>({...f,name,...(!modal.item&&!f.usernameTouched?{username:suggestUsername(name)}:{})}))}}/></Field><Field label="Usuário para entrar *" hint="Letras minúsculas, números, ponto ou hífen. Ex.: joao.silva"><Input required autoCapitalize="none" spellCheck={false} maxLength={40} pattern="[a-z0-9][a-z0-9._\-]{2,39}" value={form.username} onChange={e=>setForm(f=>({...f,username:e.target.value.toLowerCase().replace(/\s+/g,''),usernameTouched:true}))}/></Field><Field label="E-mail (opcional)" hint="Usado somente para os avisos do perfil."><Input type="email" maxLength={254} value={form.email} onChange={e=>set('email',e.target.value)}/></Field><Field label="Perfil no abastecimento *" wide><Choice value={form.role} onChange={v=>set('role',v)} options={Object.entries(roles).map(([value,label])=>({value,label}))}/></Field>{form.role==='manager'?<div className="notice wide"><Mail size={17}/><span>O gestor acessa todos os módulos e recebe os alertas de abastecimento e estoque no e-mail cadastrado.</span></div>:<><MultiCheck label="Acessos adicionais" options={Object.entries(capabilityNames).map(([value,label])=>({value,label}))} value={form.capabilities} onChange={v=>set('capabilities',v.includes('manutencao')&&!v.includes('cadastros')?[...v,'cadastros']:v)} hint="Operação: executa as etapas das OS. Acompanhamento: só consulta as OS lançadas (ex.: clientes). Manutenção inclui a liberação técnica e Cadastros gerais. Usuários e senhas continuam exclusivos do gestor."/><MultiCheck label="Organizações visíveis nas OS" options={orgs.map(o=>({value:o.id,label:`${o.acronym} · ${o.name}`}))} value={form.orgScope} onChange={v=>set('orgScope',v)} hint="Nenhuma marcada = todas. Para um cliente, marque só a organização dele: ele verá apenas as OS dela." empty="Cadastre organizações em Solicitantes e clientes."/></>}{form.role==='planner'&&<Toggle title="Receber novas solicitações por e-mail" description="Somente solicitações que precisam de planejamento." checked={!!form.notifyRequests} onChange={v=>set('notifyRequests',v)}/>}{form.role==='fueler'&&<Toggle title="Receber agendamentos por e-mail" description="Aviso para a equipe, com ou sem responsável previsto." checked={!!form.notifySchedule} onChange={v=>set('notifySchedule',v)}/>}{!modal.item&&<Field label="Senha provisória (opcional)" wide hint={`Deixe em branco para usar a senha padrão${data.access?.defaultPassword?` (${data.access.defaultPassword})`:''}. A pessoa troca no primeiro acesso.`}><Input autoComplete="off" maxLength={128} value={form.temporaryPassword} onChange={e=>set('temporaryPassword',e.target.value)}/></Field>}</>}
    {modal?.kind==='resetPassword'&&<><Field label="Senha provisória (opcional)" wide hint={`Deixe em branco para usar a senha padrão${data.access?.defaultPassword?` (${data.access.defaultPassword})`:''}.`}><Input autoComplete="off" maxLength={128} value={form.temporaryPassword} onChange={e=>set('temporaryPassword',e.target.value)}/></Field><div className="notice wide"><KeyRound size={17}/><span>Informe a senha provisória à pessoa por um canal seguro. Ela vale por {data.access?.temporaryPasswordDays||7} dias.</span></div></>}
    {modal?.kind==='checklist'&&<ChecklistEditor form={form} setForm={setForm} data={data} isNew={!modal.item} blank={blankQuestion}/>}
    {modal?.item&&!['resetPassword','checklist'].includes(modal.kind)&&<Toggle title={modal.kind==='member'?'Acesso liberado':'Cadastro ativo'} description="Desativar preserva o histórico." checked={!!form.active} onChange={v=>set('active',v)}/>}
   </div>{formError&&<div className="form-error" role="alert"><AlertTriangle size={17}/>{formError}</div>}<div className="modal-footer"><Button type="button" variant="outline" onClick={()=>setModal(null)} disabled={saving}>Voltar</Button><Button type="submit" className="primary-action" disabled={saving}>{saving?<><LoaderCircle className="animate-spin" size={16}/> Salvando…</>:modal?.kind==='resetPassword'?'Redefinir senha':modal?.kind==='checklist'?(modal.item?'Publicar nova versão':'Cadastrar checklist'):'Salvar'}</Button></div></form>
  </DialogContent></Dialog>

  <Dialog open={history!==null} onOpenChange={v=>{if(!v)setHistory(null)}}><DialogContent className="n-dialog"><DialogHeader><div className="modal-eyebrow"><History size={16}/> VERSÕES</div><DialogTitle>Histórico do checklist</DialogTitle><DialogDescription>Versões publicadas não mudam. Cada OS usa a versão vigente no momento em que o checklist foi previsto.</DialogDescription></DialogHeader>
   {history?.length?<ol className="version-list">{history.map(v=><li key={v.id}><b>v{v.version} · {v.title}</b><small>{fmt(v.created_at)} · {v.created_by_name}</small>{v.notes&&<p>{v.notes}</p>}</li>)}</ol>:<Skeleton className="h-24"/>}
  </DialogContent></Dialog>
 </div>;
}

function ChecklistEditor({form,setForm,data,isNew,blank}:{form:R,setForm:(f:(x:R)=>R)=>void,data:R,isNew:boolean,blank:()=>R}){
 const set=(key:string,value:unknown)=>setForm(f=>({...f,[key]:value}));
 const setQ=(i:number,patch:R)=>setForm(f=>({...f,questions:f.questions.map((q:R,j:number)=>{if(j!==i)return q;const next={...q,...patch};if(!next.allowNa){next.noteOn=next.noteOn.filter((x:string)=>x!=='NA')}return next})}));
 const move=(i:number,d:number)=>setForm(f=>{const qs=[...f.questions];const [q]=qs.splice(i,1);qs.splice(i+d,0,q);return {...f,questions:qs}});
 const opts=(list:string,label:(x:R)=>string,keep:string[])=>(data[list] as R[]).filter(x=>x.active||keep.includes(x.id)).map(x=>({value:x.id,label:label(x)+(x.active?'':' (inativo)')}));
 return <>
  {isNew?<Field label="Código *" hint="Ex.: CK-PRE-USO-EMP. Não muda depois."><Input required maxLength={20} value={form.code} onChange={e=>set('code',e.target.value.toUpperCase())}/></Field>:<div className="n-field"><label>Código</label><span className="tag-label">{form.code}</span></div>}
  <Field label="Momento de aplicação *"><Choice value={form.moment} onChange={v=>set('moment',v)} options={Object.entries(moments).map(([value,label])=>({value,label}))}/></Field>
  <Field label="Título *" wide><Input required maxLength={160} value={form.title} onChange={e=>set('title',e.target.value)}/></Field>
  <Field label="Descrição" wide><Textarea maxLength={1000} value={form.description} onChange={e=>set('description',e.target.value)}/></Field>
  <Field label="Instruções para quem preenche" wide><Textarea maxLength={2000} value={form.instructions} onChange={e=>set('instructions',e.target.value)}/></Field>
  <Toggle title="Obrigatório" description="Quando obrigatório, aparece como pendência na OS e pode impedir o início (pré) ou o encerramento (pós)." checked={!!form.mandatory} onChange={v=>set('mandatory',v)}/>
  <Toggle title="Uso geral" description="Disponível para qualquer OS, além dos vínculos abaixo." checked={!!form.generalUse} onChange={v=>set('generalUse',v)}/>
  <MultiCheck label="Tipos de atividade" options={opts('activityTypes',a=>`${a.code} · ${a.name}`,form.activityTypeIds)} value={form.activityTypeIds} onChange={v=>set('activityTypeIds',v)} empty="Nenhum fluxo cadastrado ainda (Planejamento › Cadastro de fluxo)."/>
  <MultiCheck label="Tipos de equipamento" options={opts('equipmentTypes',t=>t.name,form.equipmentTypeIds)} value={form.equipmentTypeIds} onChange={v=>set('equipmentTypeIds',v)}/>
  <MultiCheck label="Equipamentos específicos" options={opts('equipment',e=>e.tag,form.equipmentIds)} value={form.equipmentIds} onChange={v=>set('equipmentIds',v)} hint="Um checklist por equipamento gera um preenchimento para cada equipamento da OS."/>
  <fieldset className="n-field wide question-list"><legend>Perguntas *</legend>
   {form.questions.map((q:R,i:number)=><div className="question-card" key={q.key}>
    <div className="question-head"><b>{i+1}</b><Textarea required aria-label={`Texto da pergunta ${i+1}`} maxLength={500} value={q.text} onChange={e=>setQ(i,{text:e.target.value})} placeholder="Ex.: Os freios estão funcionando?"/><div className="question-tools"><button type="button" className="icon-action" disabled={i===0} onClick={()=>move(i,-1)} aria-label={`Subir pergunta ${i+1}`}><ArrowUp size={15}/></button><button type="button" className="icon-action" disabled={i===form.questions.length-1} onClick={()=>move(i,1)} aria-label={`Descer pergunta ${i+1}`}><ArrowDown size={15}/></button><button type="button" className="icon-action" disabled={form.questions.length===1} onClick={()=>setForm(f=>({...f,questions:f.questions.filter((_:R,j:number)=>j!==i)}))} aria-label={`Remover pergunta ${i+1}`}><Trash2 size={15}/></button></div></div>
    <div className="question-options">
     <div className="segmented" role="group" aria-label={`Alvo da pergunta ${i+1}`}>{[['atividade','Atividade'],['equipamento','Equipamento']].map(([v,l])=><button type="button" key={v} aria-pressed={q.target===v} onClick={()=>setQ(i,{target:v})}>{l}</button>)}</div>
     {[['required','Obrigatória'],['critical','Crítica'],['allowNa','Permite N/A']].map(([k,l])=><label key={k} className="inline-check"><Checkbox checked={!!q[k]} onCheckedChange={v=>setQ(i,{[k]:!!v})}/>{l}</label>)}
    </div>
    <div className="question-options">
     <span>Exige observação em:</span>{answers.filter(a=>a.value!=='NA'||q.allowNa).map(a=><label key={a.value} className="inline-check"><Checkbox checked={q.noteOn.includes(a.value)} onCheckedChange={v=>setQ(i,{noteOn:v?[...q.noteOn,a.value]:q.noteOn.filter((x:string)=>x!==a.value)})}/>{a.label}</label>)}
     </div>
    {q.critical&&q.target==='equipamento'&&<p className="question-lock"><Lock size={14}/> NC nesta pergunta bloqueia o equipamento em todo o sistema até a liberação pela Manutenção. Esse efeito não pode ser desligado.</p>}
    {q.critical&&q.target==='atividade'&&<p className="question-lock soft"><Info size={14}/> NC crítica de atividade gera impedimento local na etapa, sem bloquear equipamentos.</p>}
   </div>)}
   <Button type="button" variant="outline" onClick={()=>setForm(f=>({...f,questions:[...f.questions,blank()]}))} disabled={form.questions.length>=150}><Plus size={16}/> Adicionar pergunta</Button>
  </fieldset>
  {!isNew&&<Field label="O que mudou nesta versão" wide><Input maxLength={500} value={form.notes} onChange={e=>set('notes',e.target.value)} placeholder="Ex.: incluída pergunta sobre extintor"/></Field>}
  <div className="notice wide"><Copy size={17}/><span>Resposta vazia é diferente de N/A. Recomenda-se exigir observação em NC (o que foi encontrado) e em N/A (por que não se aplica).</span></div>
 </>;
}
